public class Main {
    // Show an int as 32 bits, padded with zeros on the left
    static String bits(int x) {
        return String.format("%32s", Integer.toBinaryString(x)).replace(' ', '0');
    }

    public static void main(String[] args) {
        int[] xs = {5, 0, -7};
        for (int x : xs) {
            System.out.println("x = " + x);
            System.out.println("  bits     = " + bits(x));
            // ~x flips every one of the 32 bits
            System.out.println("  ~x       = " + (~x) + "  bits " + bits(~x));
            // 2's complement rule: -x = ~x + 1, so ~x = -x - 1
            System.out.println("  -x - 1   = " + (-x - 1));
            // The same 32 bits read without a sign
            System.out.println("  unsigned = " + Integer.toUnsignedLong(x));
        }
    }
}
// Time O(1) per number, space O(1)

