public class Main {
    public static void main(String[] args) {
        int k = 2;
        int[] xs = {20, -20};
        for (int x : xs) {
            System.out.println("x = " + x + ", k = " + k);
            // >> copies the sign bit into the empty places on the left
            System.out.println("  x >> k  = " + (x >> k));
            // >>> always fills with 0, so a negative number turns positive
            System.out.println("  x >>> k = " + (x >>> k));
        }
        // With >>> the loop ends; with >> a negative n would stay at -1 forever
        int n = -20, steps = 0;
        while (n != 0) {
            n >>>= 1;
            steps++;
        }
        System.out.println("shifting -20 with >>> reaches 0 after " + steps + " steps");
        // lo + hi overflows int, but >>> reads the sum as 32 raw bits
        int lo = 2000000000, hi = 2100000000;
        System.out.println("safe midpoint of " + lo + " and " + hi + " = " + ((lo + hi) >>> 1));
    }
}
// Time O(1) (at most 32 loop steps), space O(1)

