public class Main {
    static String show(int n) {
        return n + " (" + Integer.toBinaryString(n) + ")";
    }

    public static void main(String[] args) {
        int n = 42;
        System.out.println("n = " + show(n));
        // Check: move bit i to position 0 and keep only that bit
        System.out.println("check bit 3: " + ((n >> 3) & 1));
        System.out.println("check bit 2: " + ((n >> 2) & 1));
        // Set: OR with the mask turns the bit ON
        System.out.println("set bit 2: " + show(n | (1 << 2)));
        // Clear: AND with the inverted mask turns the bit OFF
        System.out.println("clear bit 3: " + show(n & ~(1 << 3)));
        // Toggle: XOR with the mask flips the bit
        System.out.println("toggle bit 0: " + show(n ^ (1 << 0)));
        // Common mistake: n & mask is 8 here, not 1
        int mask = 1 << 3;
        System.out.println("n & mask = " + (n & mask));
        System.out.println("wrong test (n & mask) == 1: " + ((n & mask) == 1 ? "yes" : "no"));
        System.out.println("right test (n & mask) != 0: " + ((n & mask) != 0 ? "yes" : "no"));
    }
}
// Time O(1), space O(1) for every operation

