public class Main {
    static String show(int n) {
        return n + " (" + Integer.toBinaryString(n) + ")";
    }

    // A power of two has exactly one ON bit, so removing it leaves 0
    static boolean isPowerOfTwo(int n) {
        return n > 0 && (n & (n - 1)) == 0;
    }

    public static void main(String[] args) {
        int start = 44, n = start, count = 0;
        System.out.println("n = " + show(n));
        // Each round removes the lowest ON bit: one round per ON bit
        while (n != 0) {
            int next = n & (n - 1);
            System.out.println(n + " & " + (n - 1) + " = " + show(next));
            n = next;
            count++;
        }
        System.out.println("set bits in " + start + " = " + count);
        System.out.println("64 is a power of two: " + (isPowerOfTwo(64) ? "yes" : "no"));
        System.out.println("44 is a power of two: " + (isPowerOfTwo(44) ? "yes" : "no"));
    }
}
// Time O(number of ON bits), space O(1)

