public class Main {
    public static void main(String[] args) {
        int[] a = {4, 1, 2, 1, 2};
        System.out.println("input = " + Arrays.toString(a));
        // Start at 0 because x ^ 0 = x
        int acc = 0;
        for (int x : a) {
            // x ^ x = 0, so the second copy of a value removes the first
            acc ^= x;
            System.out.println("after " + x + ": acc = " + acc);
        }
        // Only the value without a twin is left
        System.out.println("single number = " + acc);
    }
}
// Time O(N), space O(1)

