import java.util.Arrays;

public class Main {
    // Method 1: for each bit column, count the ON bits and take count % 3
    static int byCounting(int[] a) {
        int ans = 0;
        for (int bit = 0; bit < 32; bit++) {
            int count = 0;
            for (int x : a) count += (x >> bit) & 1;
            // Triples add 0 or 3; a remainder means the single number has this bit
            if (count % 3 != 0) ans |= 1 << bit;
        }
        return ans;
    }

    // Method 2: ones and twos together count each column 0 -> 1 -> 2 -> 0
    static int byOnesTwos(int[] a) {
        int ones = 0, twos = 0;
        for (int x : a) {
            ones = (ones ^ x) & ~twos;
            twos = (twos ^ x) & ~ones;
        }
        return ones;
    }

    public static void main(String[] args) {
        int[] a = {5, -4, 5, 7, 7, 5, 7};
        System.out.println("input = " + Arrays.toString(a));
        System.out.println("count per bit, mod 3 -> " + byCounting(a));
        System.out.println("ones/twos counter    -> " + byOnesTwos(a));
    }
}
// Time O(32 * N) and O(N), space O(1) for both

