import java.util.Arrays;

public class Main {
    public static void main(String[] args) {
        int[] a = {1, 2, 1, 3, 2, 5};
        System.out.println("input = " + Arrays.toString(a));
        // Pass 1: twins cancel, so xr = first single ^ second single
        int xr = 0;
        for (int x : a) xr ^= x;
        System.out.println("xor of all = " + xr);
        // Keep only the lowest ON bit: a column where the two singles differ
        int diff = xr & -xr;
        System.out.println("lowest differing bit = " + diff);
        // Pass 2: twins land in the same group and cancel there
        int withBit = 0, withoutBit = 0;
        for (int x : a) {
            if ((x & diff) != 0) withBit ^= x;   // compare with != 0, not == 1
            else withoutBit ^= x;
        }
        System.out.println("group with that bit    -> " + withBit);
        System.out.println("group without that bit -> " + withoutBit);
    }
}
// Time O(N) (two passes), space O(1)

