using namespace std;

int main() {
    vector<int> a = {1, 2, 1, 3, 2, 5};
    cout << "input = [";
    for (size_t i = 0; i < a.size(); i++) cout << (i ? ", " : "") << a[i];
    cout << "]" << endl;
    // Pass 1: twins cancel, so xr = first single ^ second single
    unsigned xr = 0;  // unsigned keeps -xr safe even for the smallest int
    for (int x : a) xr ^= (unsigned)x;
    cout << "xor of all = " << xr << endl;
    // Keep only the lowest ON bit: a column where the two singles differ
    unsigned diff = xr & (~xr + 1);
    cout << "lowest differing bit = " << diff << endl;
    // Pass 2: twins land in the same group and cancel there
    int withBit = 0, withoutBit = 0;
    for (int x : a) {
        if (((unsigned)x & diff) != 0) withBit ^= x;   // compare with != 0, not == 1
        else withoutBit ^= x;
    }
    cout << "group with that bit    -> " << withBit << endl;
    cout << "group without that bit -> " << withoutBit << endl;
    return 0;
}
// Time O(N) (two passes), space O(1)

