import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class Main {
    public static void main(String[] args) {
        String[] items = {"a", "b", "c"};
        int n = items.length;
        System.out.println("items = " + Arrays.toString(items));
        int total = 0;
        // Every number from 0 to 2^n - 1 is one subset
        for (int mask = 0; mask < (1 << n); mask++) {
            List<String> subset = new ArrayList<>();
            StringBuilder bits = new StringBuilder();
            for (int j = 0; j < n; j++) {
                // Bit j of mask is 1 -> item j is in this subset
                if (((mask >> j) & 1) == 1) subset.add(items[j]);
                bits.insert(0, (mask >> j) & 1);
            }
            System.out.println("mask " + mask + " = " + bits + " -> {" + String.join(", ", subset) + "}");
            total++;
        }
        System.out.println("total subsets = " + total);
    }
}
// Time O(n * 2^n), extra space O(n) for the current subset

