public class Main {
    // 4-bit picture of a mask
    static String bits(int x) {
        String s = "";
        for (int j = 3; j >= 0; j--) s += (x >> j) & 1;
        return s;
    }

    public static void main(String[] args) {
        int m = 13;
        System.out.println("m = " + m + " (" + bits(m) + ")");
        int count = 0;
        // s - 1 lowers s; & m throws away the bits that are not in m
        for (int s = m; s > 0; s = (s - 1) & m) {
            System.out.println("submask " + s + " (" + bits(s) + ")");
            count++;
        }
        // The loop stops before 0, so the empty submask is handled here
        System.out.println("submask 0 (" + bits(0) + ")  <- handled separately");
        count++;
        System.out.println("submasks of m: " + count + " (2^3, m has 3 ON bits)");
        // Count every (mask, submask) pair for n = 4
        int n = 4;
        long pairs = 0;
        for (int mask = 0; mask < (1 << n); mask++) {
            pairs++;  // the empty submask
            for (int s = mask; s > 0; s = (s - 1) & mask) pairs++;
        }
        System.out.println("all (mask, submask) pairs for n = 4: " + pairs + " (3^4 = 81)");
    }
}
// Time O(2^popcount(m)) for one mask, O(3^n) over all masks; space O(1)

