public class Main {
    static int rounds;

    static int add(int a, int b) {
        rounds = 0;
        // Repeat until there is no carry left to add
        while (b != 0) {
            int carry = (a & b) << 1;  // columns where both bits are 1 carry to the left
            a = a ^ b;                 // sum of each column without the carry
            b = carry;
            rounds++;
        }
        return a;
    }

    public static void main(String[] args) {
        int[][] tests = {{5, 7}, {-3, 8}, {-5, -9}, {1, 2147483647}};
        for (int[] t : tests) {
            // int wraps at 32 bits, so negative numbers need no special case
            int sum = add(t[0], t[1]);
            System.out.println(t[0] + " + " + t[1] + " = " + sum + " (rounds: " + rounds + ")");
        }
    }
}
// Time O(32) rounds at most, so O(1); space O(1)

