import java.util.Arrays;

public class Main {
    public static void main(String[] args) {
        int[] a = {4, 14, 2};
        int n = a.length;
        System.out.println("input = " + Arrays.toString(a));
        long hamming = 0, xorSum = 0;
        // Solve each bit column on its own
        for (int bit = 0; bit < 31; bit++) {
            long ones = 0;
            for (int x : a) ones += (x >> bit) & 1;
            // A pair differs in this column when one number has 1 and the other 0
            long pairs = ones * (n - ones);
            if (pairs > 0) {
                System.out.println("bit " + bit + ": ones = " + ones + ", zeros = " + (n - ones) + ", differing pairs = " + pairs);
            }
            hamming += pairs;
            // Each differing pair adds 2^bit to its XOR
            xorSum += pairs * (1L << bit);
        }
        System.out.println("total Hamming distance = " + hamming);
        System.out.println("sum of XOR of all pairs = " + xorSum);
        // O(N^2) check
        long brute = 0;
        for (int i = 0; i < n; i++)
            for (int j = i + 1; j < n; j++) brute += a[i] ^ a[j];
        System.out.println("brute force XOR sum = " + brute);
    }
}
// Time O(31 * N) instead of O(N^2), space O(1)

