public class Main {
    // Each permission owns one bit, so a whole set fits in one int
    static final int READ = 1, WRITE = 2, EXEC = 4;

    // A named helper reads better than a raw mask test in business code
    static boolean has(int perms, int flag) {
        return (perms & flag) != 0;
    }

    public static void main(String[] args) {
        int perms = READ | EXEC;
        System.out.println("perms = " + perms + " (READ | EXEC)");
        System.out.println("can write? " + (has(perms, WRITE) ? "yes" : "no"));
        perms |= WRITE;   // grant: turn the bit ON
        System.out.println("after granting WRITE: " + perms);
        System.out.println("can write? " + (has(perms, WRITE) ? "yes" : "no"));
        perms &= ~READ;   // revoke: turn the bit OFF
        System.out.println("after revoking READ: " + perms);
        System.out.println("can read? " + (has(perms, READ) ? "yes" : "no"));
        // Hash tables with a power-of-two size replace % by a cheap mask
        int hash = 37, buckets = 16;
        System.out.println("hash 37 in 16 buckets: 37 % 16 = " + (hash % buckets) + ", 37 & 15 = " + (hash & (buckets - 1)));
    }
}
// Time O(1) per operation, space O(1): one int holds up to 32 flags

